from pathlib import Path

FILES = {'src/az_enterprise/core/director_supervisor_alpha292.py': '"""ATLAS ZERO Alpha 2.9.2 — Director Supervisor Framework.\n\nThe kernel executes work. DirectorSupervisor alone approves, rejects,\nrequests rework, or escalates the project.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom datetime import datetime, timezone\nfrom enum import Enum\nfrom typing import Any, Callable, Iterable, Mapping, Protocol, Sequence\n\n\nclass DecisionStatus(str, Enum):\n    APPROVE = "APPROVE"\n    REWORK = "REWORK"\n    REJECT = "REJECT"\n    ESCALATE = "ESCALATE"\n\n\n@dataclass(frozen=True)\nclass DirectorAction:\n    target: str\n    reason: str = ""\n\n\n@dataclass(frozen=True)\nclass DirectorDecision:\n    status: DecisionStatus\n    reason: str\n    confidence: float\n    actions: tuple[DirectorAction, ...] = ()\n    metadata: Mapping[str, Any] = field(default_factory=dict)\n\n    def __post_init__(self) -> None:\n        if not 0.0 <= self.confidence <= 1.0:\n            raise ValueError("confidence must be between 0.0 and 1.0")\n        if self.status is DecisionStatus.REWORK and not self.actions:\n            raise ValueError("REWORK decision requires at least one action")\n\n\n@dataclass(frozen=True)\nclass DecisionRecord:\n    sequence: int\n    created_at: str\n    decision: DirectorDecision\n\n\nclass DecisionLog:\n    """Small append-only decision history."""\n\n    def __init__(self) -> None:\n        self._records: list[DecisionRecord] = []\n\n    def append(self, decision: DirectorDecision) -> DecisionRecord:\n        record = DecisionRecord(\n            sequence=len(self._records) + 1,\n            created_at=datetime.now(timezone.utc).isoformat(),\n            decision=decision,\n        )\n        self._records.append(record)\n        return record\n\n    def records(self) -> tuple[DecisionRecord, ...]:\n        return tuple(self._records)\n\n    def latest(self) -> DecisionRecord | None:\n        return self._records[-1] if self._records else None\n\n\nclass RuntimePort(Protocol):\n    def run(self, targets: Sequence[str] | None = None) -> Any:\n        ...\n\n\nDecisionEvaluator = Callable[[Any, int], DirectorDecision]\n\n\n@dataclass(frozen=True)\nclass SupervisorResult:\n    final_decision: DirectorDecision\n    cycles: int\n    runtime_results: tuple[Any, ...]\n    decisions: tuple[DecisionRecord, ...]\n\n\nclass DirectorSupervisor:\n    """Single decision authority above the execution kernel."""\n\n    def __init__(\n        self,\n        runtime: RuntimePort,\n        evaluator: DecisionEvaluator,\n        *,\n        max_rework_cycles: int = 3,\n        decision_log: DecisionLog | None = None,\n    ) -> None:\n        if max_rework_cycles < 0:\n            raise ValueError("max_rework_cycles cannot be negative")\n        self._runtime = runtime\n        self._evaluator = evaluator\n        self._max_rework_cycles = max_rework_cycles\n        self._log = decision_log or DecisionLog()\n\n    @property\n    def decision_log(self) -> DecisionLog:\n        return self._log\n\n    def run_project(\n        self,\n        initial_targets: Sequence[str] | None = None,\n    ) -> SupervisorResult:\n        runtime_results: list[Any] = []\n        targets = initial_targets\n        rework_cycles = 0\n\n        while True:\n            result = self._runtime.run(targets=targets)\n            runtime_results.append(result)\n\n            decision = self._evaluator(result, rework_cycles)\n            self._log.append(decision)\n\n            if decision.status is not DecisionStatus.REWORK:\n                return SupervisorResult(\n                    final_decision=decision,\n                    cycles=len(runtime_results),\n                    runtime_results=tuple(runtime_results),\n                    decisions=self._log.records(),\n                )\n\n            if rework_cycles >= self._max_rework_cycles:\n                escalation = DirectorDecision(\n                    status=DecisionStatus.ESCALATE,\n                    reason=(\n                        "Maximum rework cycles reached. "\n                        f"Last reason: {decision.reason}"\n                    ),\n                    confidence=1.0,\n                    metadata={"last_decision": decision.status.value},\n                )\n                self._log.append(escalation)\n                return SupervisorResult(\n                    final_decision=escalation,\n                    cycles=len(runtime_results),\n                    runtime_results=tuple(runtime_results),\n                    decisions=self._log.records(),\n                )\n\n            targets = self._targets_from_actions(decision.actions)\n            rework_cycles += 1\n\n    @staticmethod\n    def _targets_from_actions(actions: Iterable[DirectorAction]) -> tuple[str, ...]:\n        targets: list[str] = []\n        seen: set[str] = set()\n        for action in actions:\n            target = action.target.strip()\n            if not target:\n                raise ValueError("DirectorAction target cannot be empty")\n            if target not in seen:\n                seen.add(target)\n                targets.append(target)\n        return tuple(targets)\n', 'tests/test_director_supervisor_alpha292.py': 'from __future__ import annotations\n\nimport pytest\n\nfrom az_enterprise.core.director_supervisor_alpha292 import (\n    DecisionLog,\n    DecisionStatus,\n    DirectorAction,\n    DirectorDecision,\n    DirectorSupervisor,\n)\n\n\nclass FakeRuntime:\n    def __init__(self) -> None:\n        self.calls = []\n\n    def run(self, targets=None):\n        normalized = None if targets is None else tuple(targets)\n        self.calls.append(normalized)\n        return {"targets": normalized, "call": len(self.calls)}\n\n\ndef test_approve_finishes_after_first_cycle():\n    runtime = FakeRuntime()\n    supervisor = DirectorSupervisor(\n        runtime,\n        lambda result, cycle: DirectorDecision(\n            status=DecisionStatus.APPROVE,\n            reason="Quality threshold reached",\n            confidence=0.94,\n        ),\n    )\n\n    result = supervisor.run_project()\n\n    assert result.final_decision.status is DecisionStatus.APPROVE\n    assert result.cycles == 1\n    assert runtime.calls == [None]\n    assert len(result.decisions) == 1\n\n\ndef test_rework_runs_only_requested_targets():\n    runtime = FakeRuntime()\n\n    def evaluator(result, cycle):\n        if cycle == 0:\n            return DirectorDecision(\n                status=DecisionStatus.REWORK,\n                reason="Visual rhythm needs correction",\n                confidence=0.87,\n                actions=(\n                    DirectorAction("visual"),\n                    DirectorAction("timeline"),\n                    DirectorAction("visual"),\n                ),\n            )\n        return DirectorDecision(\n            status=DecisionStatus.APPROVE,\n            reason="Corrections accepted",\n            confidence=0.92,\n        )\n\n    result = DirectorSupervisor(runtime, evaluator).run_project(\n        initial_targets=("research", "visual", "timeline")\n    )\n\n    assert result.cycles == 2\n    assert runtime.calls == [\n        ("research", "visual", "timeline"),\n        ("visual", "timeline"),\n    ]\n\n\ndef test_reject_does_not_rerun_runtime():\n    runtime = FakeRuntime()\n    supervisor = DirectorSupervisor(\n        runtime,\n        lambda result, cycle: DirectorDecision(\n            status=DecisionStatus.REJECT,\n            reason="Project violates mandatory constraints",\n            confidence=0.99,\n        ),\n    )\n\n    result = supervisor.run_project()\n\n    assert result.final_decision.status is DecisionStatus.REJECT\n    assert len(runtime.calls) == 1\n\n\ndef test_rework_limit_escalates():\n    runtime = FakeRuntime()\n    supervisor = DirectorSupervisor(\n        runtime,\n        lambda result, cycle: DirectorDecision(\n            status=DecisionStatus.REWORK,\n            reason="Still below threshold",\n            confidence=0.8,\n            actions=(DirectorAction("quality"),),\n        ),\n        max_rework_cycles=1,\n    )\n\n    result = supervisor.run_project()\n\n    assert runtime.calls == [None, ("quality",)]\n    assert result.final_decision.status is DecisionStatus.ESCALATE\n    assert len(result.decisions) == 3\n\n\ndef test_rework_requires_actions():\n    with pytest.raises(ValueError, match="requires at least one action"):\n        DirectorDecision(\n            status=DecisionStatus.REWORK,\n            reason="Missing actions",\n            confidence=0.7,\n        )\n\n\ndef test_confidence_range_is_validated():\n    with pytest.raises(ValueError, match="between"):\n        DirectorDecision(\n            status=DecisionStatus.APPROVE,\n            reason="invalid",\n            confidence=1.5,\n        )\n\n\ndef test_decision_log_is_append_only_snapshot():\n    log = DecisionLog()\n    first = log.append(\n        DirectorDecision(\n            status=DecisionStatus.APPROVE,\n            reason="done",\n            confidence=1.0,\n        )\n    )\n\n    snapshot = log.records()\n\n    assert first.sequence == 1\n    assert snapshot == (first,)\n    assert log.latest() == first\n', 'docs/architecture/alpha_292_director_supervisor.md': '# ATLAS ZERO Alpha 2.9.2 — Director Supervisor\n\n## Fixed architectural rule\n\nDirector AI is the only component allowed to issue the final project decision.\n\nThe kernel:\n- executes modules;\n- resolves dependencies;\n- manages cache and state;\n- reports results.\n\nThe Director Supervisor:\n- evaluates aggregated runtime results;\n- issues `APPROVE`, `REWORK`, `REJECT`, or `ESCALATE`;\n- requests targeted recomputation;\n- records every decision and its reason.\n\n## Deliberately excluded from Alpha 2.9.2\n\nTo avoid premature complexity, this release does **not** introduce:\n- Director Council;\n- multiple internal director agents;\n- autonomous self-learning;\n- event bus;\n- persistent long-term memory.\n\n`DecisionLog` is only an append-only foundation for future Director Memory.\n\n## Runtime contract\n\nThe supervisor depends on one minimal interface:\n\n```python\nruntime.run(targets: Sequence[str] | None) -> Any\n```\n\n## Rework safety\n\nRepeated rework is bounded by `max_rework_cycles`.\nWhen the limit is reached, the supervisor emits `ESCALATE` instead of looping indefinitely.\n'}

def main():
    root = Path.cwd()
    for relative_path, content in FILES.items():
        target = root / relative_path
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            backup = target.with_suffix(target.suffix + ".bak")
            backup.write_text(target.read_text(encoding="utf-8"), encoding="utf-8")
            print(f"BACKUP  {backup}")
        target.write_text(content, encoding="utf-8")
        print(f"CREATED {target}")

    print("\nRun:")
    print("python -m pytest tests/test_director_supervisor_alpha292.py -v")

if __name__ == "__main__":
    main()
